package vn.eduassistant.backend.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.eduassistant.backend.core.Json;
import vn.eduassistant.backend.db.JdbcSupport;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

@Service
public class CaseService {
    private final JdbcSupport db;private final AuditService audits;private final AppConfigHolder config;private final RealtimeHub realtime;private final RedisSupport redis;
    public CaseService(JdbcSupport db,AuditService audits,vn.eduassistant.backend.config.AppConfig config,RealtimeHub realtime,RedisSupport redis){this.db=db;this.audits=audits;this.config=new AppConfigHolder(config);this.realtime=realtime;this.redis=redis;}
    private static class AppConfigHolder { final vn.eduassistant.backend.config.AppConfig c;AppConfigHolder(vn.eduassistant.backend.config.AppConfig c){this.c=c;} }
    public Map<String,Object> get(String id){Map<String,Object> row=db.one("SELECT * FROM cases WHERE id=?",id);return format(row);}
    public List<Map<String,Object>> list(Map<String,Object> filters){StringBuilder sql=new StringBuilder("SELECT * FROM cases WHERE 1=1");List<Object>args=new ArrayList<Object>();for(String[] field:new String[][]{{"studentId","studentid"},{"status","status"},{"category","category"},{"department","assigneddepartment"}}){Object v=filters.get(field[0]);if(v!=null&&!String.valueOf(v).isEmpty()&&!("ALL".equals(v)&&!"studentId".equals(field[0]))){sql.append(" AND ").append(field[1]).append("=?");args.add(v);}}sql.append(" ORDER BY createdat DESC");if(filters.get("limit")!=null){sql.append(" LIMIT ?");args.add(Math.max(1,Math.min(50,Integer.parseInt(String.valueOf(filters.get("limit"))))));}List<Map<String,Object>>out=new ArrayList<Map<String,Object>>();for(Map<String,Object>r:db.all(sql.toString(),args.toArray()))out.add(format(r));return out;}
    public Map<String,Object> withStudent(String id){Map<String,Object> row=db.one("SELECT c.*,u.username AS \"joinedStudentUsername\",u.fullname AS \"joinedStudentFullName\",u.studentcode AS \"joinedStudentCode\",u.department AS \"joinedStudentDepartment\" FROM cases c JOIN users u ON u.id=c.studentid WHERE c.id=?",id);if(row==null)return null;Map<String,Object> student=UserService.map("id",row.get("studentId"),"username",row.remove("joinedStudentUsername"),"fullName",row.remove("joinedStudentFullName"),"studentCode",row.remove("joinedStudentCode"),"department",row.remove("joinedStudentDepartment"));return UserService.map("case",format(row),"student",student);}
    @Transactional
    public Map<String,Object> create(Map<String,Object> data,Map<String,Object> actor){String id="CASE-"+java.time.Year.now().getValue()+"-"+new java.text.SimpleDateFormat("MMddHHmmss").format(new Date())+random(3).toUpperCase();String now=Instant.now().toString();String deadline=Json.str(data.get("deadline"));if(deadline.isEmpty())deadline=Instant.now().plusSeconds(48*3600).toString();String category=first(Json.str(data.get("category")),"GENERAL");String department=first(Json.str(data.get("assignedDepartment")),"MILITARY_SERVICE_CONFIRMATION".equals(category)?"Phòng Quản lý Đào tạo":"Phòng Công tác Sinh viên");String status=first(Json.str(data.get("status")),"SUBMITTED");String studentCode=first(Json.str(actor.get("studentCode")),"UNKNOWN");String sig="APPROVED".equals(status)?sign(id+":"+studentCode+":"+first(Json.str(actor.get("fullName")),Json.str(actor.get("username")))+":APPROVED:"+now):null;
        Map<String,Object> ai=new LinkedHashMap<String,Object>(Json.object(data.get("aiExtraction")));ai.put("ruleEngine",data.get("ruleEngine"));ai.put("escalation",data.get("escalation"));
        db.update("INSERT INTO cases(id,studentid,studentname,studentcode,title,category,priority,assigneddepartment,deadline,digitalsignature,description,status,reviewresult,supplementhistory,aiextraction,evidencefiles,studentclaim,institutionalfacts,addressanalysis,createdat,updatedat) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,actor.get("id"),first(Json.str(actor.get("fullName")),Json.str(actor.get("username"))),studentCode,data.get("title"),category,first(Json.str(data.get("priority")),"MEDIUM"),department,deadline,sig,first(Json.str(data.get("description")),""),status,data.get("reviewResult")==null?null:Json.stringify(data.get("reviewResult")),null,Json.stringify(ai),Json.stringify(data.get("evidenceFiles")==null?Collections.emptyList():data.get("evidenceFiles")),json(data.get("studentClaim")),json(data.get("institutionalFacts")),json(data.get("addressAnalysis")),now,now);
        Map<String,Object> created=get(id);String reason=Json.object(data.get("escalation")).isEmpty()?"Sinh viên đã tạo mới hồ sơ #"+id+" (Điều phối: "+department+")":"[Rule Engine] Leo thang xét duyệt hồ sơ #"+id+" do ["+Json.object(data.get("escalation")).get("reason")+"]";
        audits.log("APPROVED".equals(status)?"CASE_AUTO_APPROVED":(data.get("escalation")!=null?"CASE_ESCALATED":"CASE_SUBMITTED"),actor,UserService.map("title",created.get("title"),"category",category,"priority",created.get("priority"),"status",status,"assignedDepartment",department),"SUCCESS",reason,id);
        for(Map<String,Object> staff:db.all("SELECT id FROM users WHERE role IN ('REVIEWER','ADMIN')"))notify(Json.str(staff.get("id")),"Hồ sơ mới #"+id+" cần thẩm định","Sinh viên "+created.get("studentName")+" đã nộp: \""+created.get("title")+"\" ("+department+").",Arrays.asList("HIGH","URGENT").contains(created.get("priority"))?"WARNING":"INFO",id);
        realtime.caseEvent(UserService.map("type","case_created","case",created),new HashSet<String>(Arrays.asList("REVIEWER","ADMIN")),null);redis.bumpCacheVersion("cases");redis.bumpCacheVersion("admin-stats");
        return created;
    }
    @Transactional
    public Map<String,Object> updateStatus(String id,String status,Map<String,Object> actor,String reason,Map<String,Object> extra){Map<String,Object> old=get(id);if(old==null)return null;String now=Instant.now().toString();Object review=extra.containsKey("reviewResult")?extra.get("reviewResult"):old.get("reviewResult");Object history=extra.containsKey("supplementHistory")?extra.get("supplementHistory"):old.get("supplementHistory");Object files=extra.containsKey("evidenceFiles")?extra.get("evidenceFiles"):old.get("evidenceFiles");Object department=extra.containsKey("assignedDepartment")?extra.get("assignedDepartment"):old.get("assignedDepartment");Object feedback=extra.containsKey("reviewerFeedback")?extra.get("reviewerFeedback"):old.get("reviewerFeedback");String signature=Json.str(old.get("digitalSignature"));if("APPROVED".equals(status))signature=sign(id+":"+old.get("studentCode")+":"+old.get("studentName")+":APPROVED:"+now);
        db.update("UPDATE cases SET status=?,reviewresult=?,supplementhistory=?,evidencefiles=?,assigneddepartment=?,digitalsignature=?,reviewerfeedback=?,updatedat=? WHERE id=?",status,json(review),json(history),json(files),department,signature,json(feedback),now,id);Map<String,Object>updated=get(id);audits.log("CASE_STATUS_"+status,actor,UserService.map("previousStatus",old.get("status"),"newStatus",status,"assignedDepartment",department),"SUCCESS",reason==null||reason.isEmpty()?"Cập nhật trạng thái hồ sơ từ "+old.get("status")+" sang "+status:reason,id);
        String title="Cập nhật hồ sơ #"+id;String type="WARNING";if("APPROVED".equals(status)){title="✅ Hồ sơ đã được PHÊ DUYỆT";type="SUCCESS";}else if("REJECTED".equals(status)){title="❌ Hồ sơ đã bị TỪ CHỐI";type="ERROR";}else if("REQUIRES_SUPPLEMENT".equals(status))title="⚠️ Yêu cầu BỔ SUNG MINH CHỨNG";else if("UNDER_REVIEW".equals(status))title="🔍 Hồ sơ đang được xử lý";else if("STOPPED".equals(status))title="⛔ Tiến trình xử lý hồ sơ đã bị DỪNG";notify(Json.str(old.get("studentId")),title,reason==null||reason.isEmpty()?"Trạng thái hồ sơ của bạn hiện là "+status+".":"Ghi chú cán bộ: \""+reason+"\"",type,id);realtime.caseEvent(UserService.map("type","case_updated","case",updated),new HashSet<String>(Arrays.asList("REVIEWER","ADMIN")),null);realtime.caseEvent(UserService.map("type","case_updated","case",studentView(updated)),null,Collections.singleton(Json.str(old.get("studentId"))));redis.bumpCacheVersion("cases");redis.bumpCacheVersion("admin-stats");return updated;}
    public List<Map<String,Object>> comments(String caseId){return db.all("SELECT id,caseid AS \"caseId\",authorid AS \"authorId\",authorname AS \"authorName\",authorrole AS \"authorRole\",authoravatar AS \"authorAvatar\",content,createdat AS \"createdAt\" FROM comments WHERE caseid=? ORDER BY createdat",caseId);}
    @Transactional public Map<String,Object> addComment(String caseId,Map<String,Object> author,String content,Map<String,Object> target){if(target==null)target=get(caseId);if(target==null)return null;String id="cmt_"+System.currentTimeMillis()+"_"+random(2),name=first(Json.str(author.get("fullName")),Json.str(author.get("username"))),now=Instant.now().toString(),clean=content.trim();db.update("INSERT INTO comments(id,caseid,authorid,authorname,authorrole,authoravatar,content,createdat) VALUES(?,?,?,?,?,?,?,?)",id,caseId,author.get("id"),name,author.get("role"),author.get("avatar"),clean,now);Map<String,Object> comment=UserService.map("id",id,"caseId",caseId,"authorId",author.get("id"),"authorName",name,"authorRole",author.get("role"),"authorAvatar",author.get("avatar"),"content",clean,"createdAt",now);audits.log("CASE_COMMENT_ADDED",author,UserService.map("commentId",id,"preview",clean.substring(0,Math.min(50,clean.length())),"caseId",caseId),"SUCCESS",name+" ("+author.get("role")+") đã bình luận trên hồ sơ #"+caseId,caseId);realtime.comment(caseId,UserService.map("type","comment_created","caseId",caseId,"comment",comment));
        if("STUDENT".equals(author.get("role"))){for(Map<String,Object>s:db.all("SELECT id FROM users WHERE role IN ('REVIEWER','ADMIN')"))notify(Json.str(s.get("id")),"💬 Bình luận mới trên #"+caseId,"Sinh viên "+name+": \""+clean.substring(0,Math.min(80,clean.length()))+"\"","INFO",caseId);}else if(target.get("studentId")!=null&&!target.get("studentId").equals(author.get("id")))notify(Json.str(target.get("studentId")),"💬 Cán bộ đã phản hồi trên hồ sơ #"+caseId,name+" ("+author.get("role")+"): \""+clean.substring(0,Math.min(80,clean.length()))+"\"","INFO",caseId);return comment;}
    public List<Map<String,Object>> notifications(String userId){List<Map<String,Object>>rows=db.all("SELECT id,userid AS \"userId\",title,message,type,caseid AS \"caseId\",isread AS \"isRead\",createdat AS \"createdAt\" FROM notifications WHERE userid=? ORDER BY createdat DESC",userId);return rows;}
    public void notify(String userId,String title,String message,String type,String caseId){String id="notif_"+System.currentTimeMillis()+"_"+random(2),now=Instant.now().toString();db.update("INSERT INTO notifications(id,userid,title,message,type,caseid,isread,createdat) VALUES(?,?,?,?,?,?,FALSE,?)",id,userId,title,message,type,caseId,now);redis.bumpCacheVersion("notifications:"+userId);realtime.notification(userId,UserService.map("type","notification_created","notification",UserService.map("id",id,"userId",userId,"title",title,"message",message,"type",type,"caseId",caseId,"isRead",false,"createdAt",now)));}
    public boolean markNotification(String id,String userId){boolean changed=db.update("UPDATE notifications SET isread=TRUE WHERE id=? AND userid=?",id,userId)>0;if(changed)redis.bumpCacheVersion("notifications:"+userId);return changed;}
    public void markAllNotifications(String userId){db.update("UPDATE notifications SET isread=TRUE WHERE userid=?",userId);redis.bumpCacheVersion("notifications:"+userId);}
    public boolean canVerify(String id){Map<String,Object>c=get(id);if(c==null||!"APPROVED".equals(c.get("status")))return false;String sig=Json.str(c.get("digitalSignature"));boolean valid=sig.matches("(?i)[0-9a-f]{64}")&&sig.equalsIgnoreCase(sign(id+":"+c.get("studentCode")+":"+c.get("studentName")+":APPROVED:"+c.get("updatedAt")));return valid;}
    public Map<String,Object> publicVerification(String id){Map<String,Object>c=get(id);if(c==null||!"APPROVED".equals(c.get("status")))return null;boolean verified=canVerify(id);return UserService.map("verified",verified,"caseId",id,"studentName",maskName(Json.str(c.get("studentName"))),"studentCode",maskCode(Json.str(c.get("studentCode"))),"title","Internal workflow record","category",c.get("category"),"status",c.get("status"),"assignedDepartment",c.get("assignedDepartment"),"submittedAt",c.get("createdAt"),"reviewedAt",c.get("updatedAt"),"reviewerName","Hidden for privacy","reviewerRole","SYSTEM_VERIFIED","reviewerDepartment",c.get("assignedDepartment"),"digitalSignature",c.get("digitalSignature"),"decisionNote",verified?"Chữ ký quyết định được xác thực hợp lệ.":"Không xác thực được chứng nhận: hồ sơ chưa được duyệt hoặc mã xác thực toàn vẹn không hợp lệ.");}
    public static Map<String,Object> format(Map<String,Object> row){if(row==null)return null;Map<String,Object>m=new LinkedHashMap<String,Object>(row);Map<String,Object> ai=Json.object(Json.parse(Json.str(m.get("aiExtraction"))));if(m.get("aiExtraction") instanceof Map)ai=Json.object(m.get("aiExtraction"));m.put("priority",m.get("priority")==null?"MEDIUM":m.get("priority"));m.put("evidenceFiles",parseField(m.get("evidenceFiles"),Collections.emptyList()));m.put("reviewResult",parseField(m.get("reviewResult"),null));m.put("supplementHistory",parseField(m.get("supplementHistory"),null));m.put("aiExtraction",ai.isEmpty()?null:ai);m.put("escalation",ai.get("escalation"));m.put("ruleEngine",ai.get("ruleEngine"));m.put("reviewerFeedback",parseField(m.get("reviewerFeedback"),Collections.emptyList()));m.put("studentClaim",fallback(parseField(m.get("studentClaim"),null),ai.get("studentClaim")));m.put("institutionalFacts",fallback(parseField(m.get("institutionalFacts"),null),ai.get("institutionalFacts")));m.put("addressAnalysis",fallback(parseField(m.get("addressAnalysis"),null),ai.get("addressAnalysis")));return m;}
    public static Map<String,Object> studentView(Map<String,Object> source){if(source==null)return null;Map<String,Object> m=new LinkedHashMap<String,Object>(source);for(String k:Arrays.asList("institutionalFacts","authoritativeInstitutionalFacts","ruleEngine","escalation"))m.remove(k);Map<String,Object> ai=Json.object(m.get("aiExtraction"));if(!ai.isEmpty()){ai=new LinkedHashMap<String,Object>(ai);for(String k:Arrays.asList("institutionalFacts","authoritativeInstitutionalFacts","ruleEngine","escalation"))ai.remove(k);m.put("aiExtraction",ai);}return m;}
    private String sign(String value){String key=vn.eduassistant.backend.config.AppConfig.value("SIGNATURE_KEY","");if(key.trim().length()<(config.c.production?32:16)){if(config.c.production)throw new IllegalStateException("SIGNATURE_KEY must be configured with sufficient length in production.");key="caseflow_university_dev_sign_key_2026_x889";}try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key.trim().getBytes(StandardCharsets.UTF_8),"HmacSHA256"));byte[] b=mac.doFinal(value.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte x:b)out.append(String.format("%02x",x));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
    private static Object parseField(Object val,Object fallback){if(val==null)return fallback;if(val instanceof Map||val instanceof List)return val;Object parsed=Json.parse(String.valueOf(val));return parsed==null?fallback:parsed;}
    private static Object fallback(Object one,Object two){return one==null||one instanceof Map&&((Map)one).isEmpty()?two:one;}
    private static String json(Object value){return value==null?null:Json.stringify(value);}
    private static String random(int bytes){byte[] b=new byte[bytes];new java.security.SecureRandom().nextBytes(b);StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x));return s.toString();}
    private static String first(String...s){for(String x:s)if(x!=null&&!x.trim().isEmpty())return x;return "";}
    private static String maskName(String s){String[] p=s.trim().split("\\s+");if(p.length==0)return "***";StringBuilder b=new StringBuilder();for(String x:p){if(b.length()>0)b.append(' ');b.append(x.length()<=1?x:x.charAt(0)+"***");}return b.toString();}
    private static String maskCode(String s){if(s.length()<4)return "****";return s.substring(0,Math.min(2,s.length()))+"****"+s.substring(s.length()-2);}
}
